def count_by(rows, key):
    counts = {}
    for r in rows:
        counts[r[key]] = counts.get(r[key], 0) + 1
    return counts

orders = [
    {"status": "delivered"}, {"status": "cancelled"}, {"status": "delivered"},
    {"status": "returned"}, {"status": "delivered"},
]
print(count_by(orders, "status"))

