def fetch_with_retry(call, attempts):
    for attempt in range(attempts):
        try:
            return call()
        except ConnectionError:
            if attempt == attempts - 1:
                raise


def flaky():
    flaky.n += 1
    if flaky.n < 3:
        raise ConnectionError("timeout")
    return "data"
flaky.n = 0

print(fetch_with_retry(flaky, 5))

